// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address deployer;
    function setUp() public { 
        c = new SimpleWallet();
        deployer = address(this);
    }

    function testFuzz_property(address caller, uint256 amount, bytes memory data) public {
        amount = bound(amount, 0, 1 ether);

        vm.deal(deployer, 1 ether);
        vm.deal(caller, 1 ether);

        Receiver recv = new Receiver();

        vm.prank(deployer);
        c.sendMoney(address(recv), amount, data);

        vm.deal(address(c), amount);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != deployer) {
            assertTrue(address(c).balance == amount);
        } else {
            assertTrue(address(c).balance == amount);
        }
    }
}

contract Receiver {
    receive() external payable {}
}
